"use strict";
/* ------------------------------------------------------------------ *
 * pasarguard-katabump  —  PasarGuard panel + node + Xray on KataBump   *
 * Two-file edition: index.js + package.json.  No npm dependencies.    *
 *                                                                     *
 * Layout under the KataBump root (persistent):                        *
 *   pasarguard/app        panel source (Python 3.14, patched)         *
 *   pasarguard/venv       virtualenv with the uv.lock pinned deps     *
 *   pasarguard/python     portable CPython 3.14 (only if needed)      *
 *   pasarguard/node       PasarGuard node binary + .env               *
 *   pasarguard/xray-core  xray-core + geoip/geosite                   *
 *   pasarguard/certs      self-signed TLS cert for the local node     *
 *   pasarguard/data       SQLite database (persistent!)               *
 *   pasarguard/log        panel / node / xray logs                    *
 * ------------------------------------------------------------------ */

require("v8").setFlagsFromString("--max-old-space-size=48");
const releaseMemory = () => {
  if (typeof global.gc === "function") {
    try { global.gc(); } catch (e) {}
  }
};

const net = require("net");
const http = require("http");
const https = require("https");
const fs = require("fs");
const path = require("path");
const zlib = require("zlib");
const os = require("os");
const crypto = require("crypto");
const { spawn } = require("child_process");
const { once } = require("events");

