const UA = "pasarguard-katabump/1.0";
const REPO = "PasarGuard/panel";
const NODE_REPO = "PasarGuard/node";

const PG_VERSION = process.env.PASARGUARD_VERSION || "v5.4.1";
const NODE_VERSION = process.env.PASARGUARD_NODE_VERSION || "v0.5.4";
const XRAY_VERSION = process.env.XRAY_VERSION || "latest";
