const PY_VERSION = process.env.PASARGUARD_PYTHON_VERSION || "3.14.8";

const STATUS_PATH = "/_kb/status";
const TUNNEL_DEFAULT = "vless:/mb-vless:21001";
const INBOUND_TAG = "KATABUMP_VLESS_WS";
const ADMIN_USER = process.env.ADMIN_USER || "admin";
const ADMIN_PASS = process.env.ADMIN_PASS || "";

const ROOT = process.env.KATABUMP_ROOT || process.env.KATABUMP_DIR || process.cwd();
const BASE = path.join(ROOT, "pasarguard");
const APP = path.join(BASE, "app");
