const PYLIBS = path.join(BASE, "pylibs");
const PORTABLE = path.join(BASE, "python");
const NODE_DIR = path.join(BASE, "node");
const XRAY_DIR = path.join(BASE, "xray-core");
const CERT_DIR = path.join(BASE, "certs");
const DASH_DIR = path.join(APP, "dashboard", "build");
const DATA = path.join(BASE, "data");
const LOGS = path.join(BASE, "log");
