const STATE_FILE = path.join(BASE, "state.json");
const CRED_FILE = path.join(BASE, "PANEL.txt");
const PINS_FILE = path.join(BASE, "requirements.lock.txt");
const ENV_FILE = path.join(APP, ".env");
