const NODE_ENV_FILE = path.join(NODE_DIR, ".env");
const NODE_KEY_FILE = path.join(NODE_DIR, "api_key.txt");

const SKIP_XRAY = process.env.PASARGUARD_SKIP_XRAY === "1";
const FORCE_SETUP = process.env.PASARGUARD_FORCE_SETUP === "1";
const TELEGRAM_BOT = process.env.PASARGUARD_TELEGRAM_BOT === "1";
const AUTO_GROUP = process.env.PASARGUARD_AUTO_GROUP !== "0";
const PANEL_MEM_MAX = int(process.env.PASARGUARD_PANEL_MEM_MAX, 205); // MB; restart the panel above this
const PUBLIC_HOST_ENV = (process.env.PASARGUARD_PUBLIC_HOST || "").trim();

/* ------------------------------ ports ----------------------------- */

function int(v, dflt) {
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : dflt;
}

function firstFreePort(candidates) {
  return new Promise((resolve) => {
    let i = 0;
    const tryNext = () => {
      if (i >= candidates.length) return resolve(candidates[candidates.length - 1]);
      const port = candidates[i++];
      const srv = net.createServer();
      srv.once("error", () => { try { srv.close(); } catch (e) {} tryNext(); });
      srv.once("listening", () => srv.close(() => resolve(port)));
      srv.listen(port, "127.0.0.1");
    };
    tryNext();
  });
}

const PUBLIC_PORT = int(process.env.SERVER_PORT || process.env.PORT, 3000);
let PANEL_PORT = int(process.env.PANEL_PORT, 8000);
let NODE_PORT = int(process.env.PASARGUARD_NODE_PORT, 62050);
let NODE_API_PORT = int(process.env.PASARGUARD_NODE_API_PORT, 62051);
let XRAY_PORT = int(process.env.PASARGUARD_XRAY_PORT, 21001);

function parseTunnels(spec) {
  const out = [];
  for (const raw of String(spec || "").split(/[,\n]/)) {
    const p = raw.trim().split(":");
    if (p.length < 3) continue;
    const port = int(p[2], 0);
    if (!p[1] || !port) continue;
    out.push({ proto: (p[0] || "vless").toLowerCase(), path: p[1].startsWith("/") ? p[1] : "/" + p[1], port });
  }
  if (!out.length) {
    const p = TUNNEL_DEFAULT.split(":");
    out.push({ proto: p[0], path: p[1], port: int(p[2], 21001) });
  }
  return out;
}
const TUNNELS = parseTunnels(process.env.PASARGUARD_TUNNELS || TUNNEL_DEFAULT);

/* ------------------------------ logging --------------------------- */

const STATE = {
  wrapper: WRAPPER,
  pasarguard: null,
  node: null,
  publicPort: PUBLIC_PORT,
  panelPort: PANEL_PORT,
  panelUp: false,
  coreUp: false,
  step: "booting",
  error: null,
  admin: null,
  publicHost: null,
  tunnels: TUNNELS,
  data: DATA,
};

const C = process.stdout.isTTY || process.env.FORCE_COLOR === "1";
const paint = (c, s) => (C ? `\x1b[${c}m${s}\x1b[0m` : s);
const log = (...a) => console.log("[pasarguard]", ...a);
const ok = (...a) => console.log(paint("32", "  ✓"), ...a);
const warn = (...a) => console.log(paint("33", "  !"), ...a);
const err = (...a) => console.log(paint("31", "  ✗"), ...a);
const step = (s) => {
  STATE.step = s;
  console.log(paint("36", "  ›"), s);
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function fmtBytes(n) {
  if (n >= 1e9) return (n / 1e9).toFixed(1) + " GB";
  if (n >= 1e6) return (n / 1e6).toFixed(1) + " MB";
  if (n >= 1e3) return (n / 1e3).toFixed(0) + " KB";
  return n + " B";
}

function randomToken(len) {
  return crypto.randomBytes(Math.ceil(len * 0.75)).toString("base64").replace(/[+/=]/g, "").slice(0, len);
}
function uuid4() {
  const b = crypto.randomBytes(16);
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = b.toString("hex");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

/* ------------------------------ state ----------------------------- */

function readState() {
  try {
    return JSON.parse(fs.readFileSync(STATE_FILE, "utf8"));
  } catch (e) {
    return {};
  }
}
function saveState(patch) {
  try {
    const cur = readState();
    fs.writeFileSync(STATE_FILE, JSON.stringify(Object.assign(cur, patch, { at: Date.now() }), null, 2));
  } catch (e) {}
}

function ensureDir(p) {
  fs.mkdirSync(p, { recursive: true });
}
function ensureDirs() {
  for (const d of [BASE, APP, DATA, LOGS, TMP, NODE_DIR, XRAY_DIR, CERT_DIR]) ensureDir(d);
}
function rmrf(p) {
  try {
    fs.rmSync(p, { recursive: true, force: true });
  } catch (e) {
    try {
      fs.rmdirSync(p, { recursive: true });
    } catch (e2) {}
  }
}

/* ------------------------------ http ------------------------------ */

function request(url, opts = {}) {
  return new Promise((resolve, reject) => {
    let u;
    try {
      u = new URL(url);
    } catch (e) {
      return reject(new Error("bad url " + url));
    }
    const mod = u.protocol === "https:" ? https : http;
    const payload = opts.body ? Buffer.from(opts.body) : null;
    const headers = Object.assign({ "User-Agent": UA }, opts.headers || {});
    if (payload) headers["Content-Length"] = payload.length;
    const req = mod.request(
      {
        protocol: u.protocol,
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname + u.search,
        method: opts.method || (payload ? "POST" : "GET"),
        headers,
        timeout: opts.timeout || 30000,
      },
      (res) => {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          res.resume();
          const next = new URL(res.headers.location, url).toString();
          if ((opts.redirects || 0) > 5) return reject(new Error("too many redirects"));
          return resolve(request(next, Object.assign({}, opts, { redirects: (opts.redirects || 0) + 1 })));
        }
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks) }));
      }
    );
    req.on("timeout", () => req.destroy(new Error("timeout")));
    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

async function downloadFile(url, dest, label) {
  const tmp = dest + ".part";
  rmrf(tmp);
  let done = 0;
  let last = 0;
  await new Promise((resolve, reject) => {
    const doit = (target) => {
      let u;
      try {
        u = new URL(target);
      } catch (e) {
        return reject(new Error("bad url " + target));
      }
      const mod = u.protocol === "https:" ? https : http;
      const req = mod.get(
        {
          protocol: u.protocol,
          hostname: u.hostname,
          port: u.port || (u.protocol === "https:" ? 443 : 80),
          path: u.pathname + u.search,
          headers: { "User-Agent": UA },
          timeout: 30000,
        },
        (res) => {
          if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
            res.resume();
            return doit(new URL(res.headers.location, target).toString());
          }
          if (res.statusCode !== 200) {
            res.resume();
            return reject(new Error(`${label}: HTTP ${res.statusCode}`));
          }
          const total = int(res.headers["content-length"], 0);
          const out = fs.createWriteStream(tmp);
          res.on("data", (c) => {
            done += c.length;
            const now = Date.now();
            if (now - last > 4000) {
              last = now;
              process.stdout.write(
                `\r  … ${label} ${fmtBytes(done)}${total ? " / " + fmtBytes(total) : ""}   `
              );
            }
          });
          res.on("error", reject);
          out.on("error", reject);
          out.on("finish", () => {
            if (total && done < total * 0.98) return reject(new Error(`${label}: truncated`));
            process.stdout.write(`\r  … ${label} ${fmtBytes(done)}          \n`);
            out.close(() => resolve());
          });
          res.pipe(out);
        }
      );
      req.on("timeout", () => req.destroy(new Error(`${label}: timeout`)));
      req.on("error", reject);
    };
    doit(url);
  });
  fs.renameSync(tmp, dest);
  return fs.statSync(dest).size;
}

/* ------------------------------ tar ------------------------------- */

function octal(buf, start, len) {
  const s = buf.toString("ascii", start, start + len).replace(/\0/g, " ").trim();
  if (!s) return 0;
  return parseInt(s, 8) || 0;
}
function parsePax(buf) {
  const out = {};
  let i = 0;
  while (i < buf.length) {
    const sp = buf.indexOf(32, i);
    if (sp < 0) break;
    const len = parseInt(buf.toString("ascii", i, sp), 10);
    if (!len) break;
    const rec = buf.toString("utf8", i, i + len);
    const eq = rec.indexOf("=");
    if (eq > 0) {
      let k = rec.slice(rec.indexOf(" ") + 1, eq);
      let v = rec.slice(eq + 1).replace(/\n$/, "");
      out[k] = v;
    }
    i += len;
  }
  return out;
}
function parseTarHeader(h, longName, longLink, pax) {
  let name = h.toString("utf8", 0, 100).replace(/\0.*$/, "");
  if (longName) name = longName;
  else if (pax && pax.path) name = pax.path;
  const size = pax && pax.size !== undefined ? parseInt(pax.size, 10) : octal(h, 124, 12);
  const typeflag = String.fromCharCode(h[156] || 0);
  let linkname = h.toString("utf8", 157, 257).replace(/\0.*$/, "");
  if (longLink) linkname = longLink;
  else if (pax && pax.linkpath) linkname = pax.linkpath;
  const mode = octal(h, 100, 8) & 0o777;
  const prefix = h.toString("utf8", 345, 500).replace(/\0.*$/, "");
  if (prefix && !name.startsWith("/") && typeflag !== "L" && typeflag !== "K") name = prefix + "/" + name;
  return { name, size, typeflag, linkname, mode, mtime: octal(h, 136, 12) };
}
function isZeroBlock(b) {
  for (let i = 0; i < b.length; i++) if (b[i] !== 0) return false;
  return true;
}
function safeJoin(destDir, name) {
  const norm = path.normalize(name).replace(/^(\.\.[/\\])+/, "");
  const full = path.join(destDir, norm);
  if (!full.startsWith(path.resolve(destDir))) return null;
  return full;
}

/* --------- streaming extraction: keeps the peak RSS flat --------- */
/* Unpacking a 36 MB tarball into a Buffer costs ~120 MB of RSS that V8 never
   hands back to the OS, which is fatal on a 308 MB plan. Every archive is
   therefore unpacked through a temp file with fixed-size buffers: peak cost
   is a few hundred KB instead of 5x the payload. */

const B64_TABLE = (function () {
  const t = new Int8Array(256).fill(-1);
  const a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  for (let i = 0; i < a.length; i++) t[a.charCodeAt(i)] = i;
  return t;
})();
const B64_STATE = { acc: 0, bits: 0 };

function b64Feed(bytes) {
  const out = Buffer.allocUnsafe(((bytes.length * 3) >> 2) + 3);
  let n = 0;
  for (let i = 0; i < bytes.length; i++) {
    const v = B64_TABLE[bytes[i]];
    if (v < 0) continue; // newlines, padding, comment characters
    B64_STATE.acc = (B64_STATE.acc << 6) | v;
    B64_STATE.bits += 6;
    if (B64_STATE.bits >= 8) {
      B64_STATE.bits -= 8;
      out[n++] = (B64_STATE.acc >> B64_STATE.bits) & 0xff;
    }
  }
  return out.subarray(0, n);
}

function readExact(fd, buf, len) {
  let got = 0;
  while (got < len) {
    let r = 0;
    try {
      r = fs.readSync(fd, buf, got, len - got, null);
    } catch (e) {
      r = 0;
    }
    if (!r) return false;
    got += r;
  }
  return true;
}

function skipBytes(fd, n) {
  if (n <= 0) return true;
  const b = Buffer.allocUnsafe(Math.min(n, 1 << 16));
  let left = n;
  while (left > 0) {
    let r = 0;
    try {
      r = fs.readSync(fd, b, 0, Math.min(b.length, left), null);
    } catch (e) {
      return false;
    }
    if (!r) return false;
    left -= r;
  }
  return true;
}

function extractTarFile(tarPath, destDir, strip = 0) {
  fs.mkdirSync(destDir, { recursive: true });
  const fd = fs.openSync(tarPath, "r");
  const hdr = Buffer.allocUnsafe(512);
  const chunk = Buffer.allocUnsafe(1 << 18);
  let longName = null;
  let longLink = null;
  let pax = null;
  let count = 0;
  try {
    for (;;) {
      if (!readExact(fd, hdr, 512)) break;
      if (isZeroBlock(hdr)) break;
      const h = parseTarHeader(hdr, longName, longLink, pax);
      const size = h.size;
      const padded = Math.ceil(size / 512) * 512;

      if (h.typeflag === "L" || h.typeflag === "K" || h.typeflag === "x" || h.typeflag === "g") {
        const p = Buffer.allocUnsafe(size);
        if (!readExact(fd, p, size)) break;
        skipBytes(fd, padded - size);
        const txt = p.toString("utf8");
        if (h.typeflag === "L") {
          longName = txt.replace(/\0.*$/, "");
          pax = null;
        } else if (h.typeflag === "K") {
          longLink = txt.replace(/\0.*$/, "");
        } else {
          pax = parsePax(p);
        }
        continue;
      }
      longName = null;
      longLink = null;
      pax = null;

      let name = h.name;
      if (strip) {
        const parts = name.split("/");
        if (parts.length <= strip) {
          skipBytes(fd, padded);
          continue;
        }
        name = parts.slice(strip).join("/");
      }
      if (!name || name === "." || name === "./") {
        skipBytes(fd, padded);
        continue;
      }
      const target = safeJoin(destDir, name);
      if (!target) {
        skipBytes(fd, padded);
        continue;
      }

      if (h.typeflag === "5") {
        fs.mkdirSync(target, { recursive: true });
        skipBytes(fd, padded);
      } else if (h.typeflag === "0" || h.typeflag === "" || h.typeflag === "7") {
        fs.mkdirSync(path.dirname(target), { recursive: true });
        const out = fs.openSync(target, "w");
        let left = size;
        while (left > 0) {
          const want = Math.min(chunk.length, left);
          let r = 0;
          try {
            r = fs.readSync(fd, chunk, 0, want, null);
          } catch (e) {
            r = 0;
          }
          if (!r) break;
          fs.writeSync(out, chunk, 0, r);
          left -= r;
        }
        fs.closeSync(out);
        if (left > 0) skipBytes(fd, left);
        skipBytes(fd, padded - size);
        if (h.mode & 0o111) {
          try {
            fs.chmodSync(target, 0o755);
          } catch (e) {}
        }
        count++;
      } else if (h.typeflag === "2") {
        try {
          fs.mkdirSync(path.dirname(target), { recursive: true });
          try {
            fs.unlinkSync(target);
          } catch (e) {}
          fs.symlinkSync(h.linkname, target);
        } catch (e) {
          try {
            const src = safeJoin(destDir, h.linkname);
            if (src && fs.existsSync(src)) fs.copyFileSync(src, target);
          } catch (e2) {}
        }
        skipBytes(fd, padded);
      } else if (h.typeflag === "1") {
        try {
          const src = safeJoin(destDir, h.linkname);
          if (src) fs.linkSync(src, target);
        } catch (e) {}
        skipBytes(fd, padded);
      } else {
        skipBytes(fd, padded);
      }
    }
  } finally {
    try {
      fs.closeSync(fd);
    } catch (e) {}
  }
  return count;
}

function streamDecompress(src, dest, kind) {
  return new Promise((resolve, reject) => {
    let rs = null;
    let dz = null;
    let ws = null;
    let settled = false;
    const fail = (e) => {
      if (settled) return;
      settled = true;
      try {
        rs && rs.destroy();
      } catch (x) {}
      try {
        dz && dz.destroy();
      } catch (x) {}
      try {
        ws && ws.destroy();
      } catch (x) {}
      reject(e);
    };
    rs = fs.createReadStream(src, { highWaterMark: 1 << 18 });
    ws = fs.createWriteStream(dest, { highWaterMark: 1 << 18 });
    rs.on("error", fail);
    ws.on("error", fail);
    try {
      dz = kind === "brotli" ? zlib.createBrotliDecompress() : zlib.createGunzip();
    } catch (e) {
      return fail(e);
    }
    dz.on("error", fail);
    ws.on("finish", () => {
      if (settled) return;
      settled = true;
      resolve(true);
    });
    rs.pipe(dz).pipe(ws);
  });
}
async function extractCompressedTar(srcPath, destDir, strip = 0, kind = "gzip") {
  fs.mkdirSync(TMP, { recursive: true });
  const tarPath = path.join(TMP, `kb-${process.pid}-${Date.now()}.tar`);
  try {
    await streamDecompress(srcPath, tarPath, kind);
    return extractTarFile(tarPath, destDir, strip);
  } finally {
    try {
      fs.unlinkSync(tarPath);
    } catch (e) {}
  }
}

async function extractTarGz(gzPath, destDir, strip = 0) {
  return extractCompressedTar(gzPath, destDir, strip, "gzip");
}

/* ------------------------------ shell ----------------------------- */

function run(cmd, args, opts = {}) {
  return new Promise((resolve) => {
    const quiet = opts.quiet !== false;
    const filter = opts.filter || null;
    const show = opts.show || null;
    let out = "";
    let hidden = 0;
    const child = spawn(cmd, args, {
      cwd: opts.cwd || APP,
      env: Object.assign({}, process.env, opts.env || {}),
      stdio: ["ignore", "pipe", "pipe"],
    });
    let timer = null;
    if (opts.timeout) timer = setTimeout(() => { try { child.kill("SIGKILL"); } catch (e) {} }, opts.timeout);
    const handle = (chunk) => {
      const s = chunk.toString();
      out += s;
      for (const line of s.split("\n")) {
        if (!line.trim()) continue;
        if (filter && !filter.test(line)) continue;
        if (show && !show.test(line)) {
          if (quiet) { hidden++; continue; }
        }
        if (quiet) hidden++;
        else console.log("      " + line.replace(/\s+$/, ""));
      }
    };
    child.stdout.on("data", handle);
    child.stderr.on("data", handle);
    child.on("error", (e) => {
      if (timer) clearTimeout(timer);
      resolve({ code: 1, out: out + "\n" + e.message });
    });
    child.on("close", (code) => {
      if (timer) clearTimeout(timer);
      resolve({ code: code || 0, out });
    });
  });
}

async function pyEval(py, script, opts = {}) {
  const r = await run(py, ["-c", script], Object.assign({ quiet: true }, opts));
  return r.code === 0 ? r.out.trim() : null;
}

/* ---------------------------- python 3.14 ------------------------- */

function pbsAsset() {
  const arch = process.arch;
  const map = { x64: "x86_64-unknown-linux-gnu", arm64: "aarch64-unknown-linux-gnu" };
  const triple = map[arch];
  if (!triple) throw new Error("unsupported architecture for portable python: " + arch);
  return `cpython-${PY_VERSION}+${PY_BUILD}-${triple}-install_only_stripped.tar.gz`;
}

async function pythonVersion(cand) {
  const r = await run(cand, ["-c", "import sys,platform;print('%d.%d.%d'%sys.version_info[:3])"], { quiet: true, timeout: 30000 });
  if (r.code !== 0) return null;
  const m = r.out.trim().match(/(\d+)\.(\d+)\.(\d+)/);
  return m ? { text: m[0], major: +m[1], minor: +m[2], patch: +m[3] } : null;
}

function usable(v) {
  return v && v.major === 3 && v.minor >= 14;
}

async function findSystemPython() {
  const cands = [
    process.env.PASARGUARD_PYTHON,
    "python3.14",
    "python3",
    "python",
    "/usr/bin/python3.14",
    "/usr/bin/python3",
  ].filter(Boolean);
  for (const c of cands) {
    const v = await pythonVersion(c);
    if (usable(v)) {
      ok(`python found: ${c} (${v.text})`);
      return c;
    }
  }
  return null;
}

function portableCandidates() {
  return ["python3", "python3.14", "python"].map((n) => path.join(PORTABLE, "bin", n));
}

async function installPortablePython() {
  for (const cand of portableCandidates()) {
    const v = await pythonVersion(cand);
    if (usable(v)) return cand;
  }
  const marker = portableCandidates()[0];

  step("installing portable CPython " + PY_VERSION + " (no root needed)");
  const asset = pbsAsset();
  const url = `https://github.com/astral-sh/python-build-standalone/releases/download/${PY_BUILD}/${asset}`;
  const dest = path.join(TMP, asset);
  rmrf(PORTABLE);
  await downloadFile(url, dest, "python " + PY_VERSION);
  await extractTarGz(dest, PORTABLE, 1);
  rmrf(dest);
  for (const cand of portableCandidates()) {
    try { fs.chmodSync(cand, 0o755); } catch (e) {}
    const v2 = await pythonVersion(cand);
    if (usable(v2)) {
      ok(`portable python ready: ${v2.text}`);
      return cand;
    }
  }
  throw new Error(
    "portable python did not work. extracted files: " +
      (() => { try { return fs.readdirSync(path.join(PORTABLE, "bin")).join(","); } catch (e) { return "?"; } })()
  );
}

async function findPython() {
  const sys = await findSystemPython();
  if (sys) return sys;
  return await installPortablePython();
}

/* ---------------------------- utilities --------------------------- */

function portOpen(port, timeout = 1200) {
  return new Promise((resolve) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let done = false;
    const finish = (v) => {
      if (done) return;
      done = true;
      try { sock.destroy(); } catch (e) {}
      resolve(v);
    };
    sock.setTimeout(timeout);
    sock.once("connect", () => finish(true));
    sock.once("timeout", () => finish(false));
    sock.once("error", () => finish(false));
  });
}

async function detectPublicIp() {
  if (PUBLIC_HOST_ENV) return PUBLIC_HOST_ENV;
  for (const url of ["https://api.ipify.org", "https://icanhazip.com", "https://ifconfig.io/ip"]) {
    try {
      const r = await request(url, { timeout: 6000 });
      const ip = r.body.toString().trim();
      if (/^\d+\.\d+\.\d+\.\d+$/.test(ip)) return ip;
    } catch (e) {}
  }
  return null;
}

function killOrphans() {
  // kill stale panel / node / xray processes from a previous run of THIS wrapper
  const markers = [path.join(APP, "main.py"), NODE_DIR, XRAY_DIR, path.join(BASE, "venv")];
  const me = process.pid;
  const scan = (d) => {
    let pids = [];
    try {
      pids = fs.readdirSync(d).filter((f) => /^\d+$/.test(f));
    } catch (e) {
      return;
    }
    for (const pid of pids) {
      const p = Number(pid);
      if (!p || p === me) continue;
      let cmd = "";
      try {
        cmd = fs.readFileSync(`/proc/${p}/cmdline`, "utf8").replace(/\0/g, " ");
      } catch (e) {
        continue;
      }
      if (!cmd) continue;
      if (!/(main\.py|pasarguard-node|xray|uvicorn)/.test(cmd)) continue;
      if (!markers.some((m) => cmd.includes(m))) continue;
      try {
        process.kill(p, "SIGKILL");
        warn(`killed stale process ${p}`);
      } catch (e) {}
    }
  };
  scan("/proc");
}

function killTree(child) {
  if (!child || !child.pid) return;
  try {
    process.kill(-child.pid, "SIGTERM");
  } catch (e) {
    try { child.kill("SIGTERM"); } catch (e2) {}
  }
}
/* ================================================================== *
 *  installation steps                                                *
 * ================================================================== */

// NOTE: the markers are split so that they never appear verbatim in this source;
// installDashboard() looks for them with lastIndexOf() anyway.
const DASH_BEGIN = "/*__PG_DASH" + "BOARD_BEGIN__";
const DASH_END = "__PG_DASH" + "BOARD_END__*/";

function panelVersion() {
  try {
    const s = fs.readFileSync(path.join(APP, "app", "version.py"), "utf8");
    const m = s.match(/"([0-9]+\.[0-9]+\.[0-9]+)"/);
    return m ? m[1] : null;
  } catch (e) {
    return null;
  }
}

async function installPanelSource(force) {
  const cur = panelVersion();
  if (!force && cur && fs.existsSync(path.join(APP, "main.py")) && fs.existsSync(path.join(APP, "uv.lock"))) {
    ok(`panel source present (v${cur})`);
    return cur;
  }
  step(`downloading PasarGuard ${PG_VERSION} source`);
  rmrf(APP);
  ensureDir(APP);
  const url = `https://codeload.github.com/${REPO}/tar.gz/refs/tags/${PG_VERSION}`;
  const tgz = path.join(TMP, `panel-${PG_VERSION}.tar.gz`);
  await downloadFile(url, tgz, "pasarguard source");
  const n = await extractTarGz(tgz, APP, 1);
  rmrf(tgz);
  const v = panelVersion();
  if (!v) throw new Error("panel source extraction failed");
  ok(`pasarguard v${v} extracted (${n} files)`);
  releaseMemory();
  return v;
}

/* --- upstream bug fix: v5.4.1 ships python-2 style `except A, B:` --- */
const EXCEPT_RE = /^(\s*)except\s+([A-Za-z_][\w.]*(?:\s*,\s*[A-Za-z_][\w.]*)+)\s*:\s*$/gm;

function fixPy2Except(dir) {
  let files = 0;
  let hits = 0;
  const walk = (d) => {
    let entries = [];
    try {
      entries = fs.readdirSync(d, { withFileTypes: true });
    } catch (e) {
      return;
    }
    for (const e of entries) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) {
        if (e.name === "__pycache__") continue;
        walk(p);
      } else if (e.name.endsWith(".py")) {
        let src;
        try {
          src = fs.readFileSync(p, "utf8");
        } catch (er) {
          continue;
        }
        if (!EXCEPT_RE.test(src)) continue;
        EXCEPT_RE.lastIndex = 0;
        const patched = src.replace(EXCEPT_RE, (m, indent, names) => {
          hits++;
          return `${indent}except (${names
            .split(",")
            .map((s) => s.trim())
            .join(", ")}):`;
        });
        if (patched !== src) {
          fs.writeFileSync(p, patched);
          files++;
        }
      }
    }
  };
  walk(dir);
  return { files, hits };
}

/* --- memory savers: keep aiogram (Telegram bot, ~120 MB) unloaded --- */
const LAZY_PATCHES = [
  {
    file: path.join("app", "app_factory.py"),
    find: "        from app import telegram  # noqa: F401\n",
    drop: true,
    anchor: "        import dashboard\n",
    addImport: { find: "import warnings\n", insert: "import os\nimport warnings\n" },
    insert:
      "        # [katabump] telegram bot is opt-in: importing it loads aiogram (~120 MB RSS)\n" +
      '        if os.getenv("PASARGUARD_TELEGRAM_BOT", "0") == "1":\n' +
      "            from app import telegram  # noqa: F401\n",
  },
  {
    file: path.join("app", "routers", "system.py"),
    find: "from aiogram.types import Update\n",
    drop: true,
    anchor: '    update = Update.model_validate(update_data, context={"bot": bot})\n',
    insert: "    from aiogram.types import Update  # [katabump] lazy\n",
    addImport: { find: "import time\n", insert: "import os\nimport time\n" },
  },
  {
    file: path.join("app", "routers", "system.py"),
    find: "from app.telegram import get_bot, get_dispatcher\n",
    drop: true,
    anchor: "    bot = get_bot()\n",
    insert: "    from app.telegram import get_bot, get_dispatcher  # [katabump] lazy\n",
  },
  {
    file: path.join("app", "routers", "authentication.py"),
    find: "from aiogram.utils.web_app import WebAppInitData, safe_parse_webapp_init_data\n",
    drop: true,
    anchor: "    try:\n        data: WebAppInitData = safe_parse_webapp_init_data(",
    insert:
      "    from aiogram.utils.web_app import WebAppInitData, safe_parse_webapp_init_data  # [katabump] lazy\n",
  },
  {
    file: path.join("app", "operation", "settings.py"),
    find: "from app.telegram import startup_telegram_bot\n",
    drop: true,
    anchor: "            await startup_telegram_bot()\n",
    insert: "            from app.telegram import startup_telegram_bot  # [katabump] lazy\n",
  },
];

function applyLazyPatches() {
  let applied = 0;
  const missing = [];
  for (const p of LAZY_PATCHES) {
    const file = path.join(APP, p.file);
    let src;
    try {
      src = fs.readFileSync(file, "utf8");
    } catch (e) {
      missing.push(p.file + " (missing)");
      continue;
    }
    // already patched?  (the inserted block sits immediately before the anchor)
    if (src.includes(p.insert + p.anchor)) {
      applied++;
      continue;
    }
    if (!src.includes(p.find)) {
      missing.push(p.file + " :: " + p.find.trim().slice(0, 60));
      continue;
    }
    let next = src.replace(p.find, "");
    if (p.addImport && !next.includes(p.addImport.insert)) {
      if (next.includes(p.addImport.find)) next = next.replace(p.addImport.find, p.addImport.insert);
      else next = p.addImport.insert + next;
    }
    if (!next.includes(p.anchor)) {
      // anchor moved: keep the original import untouched rather than corrupting the file
      missing.push(p.file + " :: anchor missing");
      continue;
    }
    next = next.replace(p.anchor, p.insert + p.anchor);
    fs.writeFileSync(file, next);
    applied++;
  }
  return { applied, missing };
}

async function patchSources(py) {
  step("patching upstream sources for this environment");
  const e = fixPy2Except(APP);
  if (e.files) ok(`fixed ${e.hits} python-2 \`except A, B:\` statements in ${e.files} files`);
  let l = applyLazyPatches();
  if (l.applied) ok(`made ${l.applied} Telegram/aiogram imports lazy (saves ~120 MB)`);
  for (const m of l.missing) warn(`patch not applied: ${m}`);

  // the patches edit upstream python, so make sure the result still compiles;
  // if it does not, re-extract the source and patch it once more from scratch
  if (py && l.applied) {
    const files = LAZY_PATCHES.map((p) => path.join(APP, p.file));
    files.push(path.join(APP, "main.py"), path.join(APP, "config.py"));
    const r = await run(py, ["-m", "py_compile"].concat(files), { quiet: true, timeout: 120000 });
    if (r.code !== 0) {
      warn("patched sources failed to compile — re-extracting a clean copy");
      await installPanelSource(true);
      fixPy2Except(APP);
      l = applyLazyPatches();
      const r2 = await run(py, ["-m", "py_compile"].concat(files), { quiet: true, timeout: 120000 });
      if (r2.code !== 0) throw new Error("patched panel sources do not compile:\n" + r2.out.slice(-800));
      ok("patched sources verified");
    }
  }
  if (!TELEGRAM_BOT) log("     telegram bot disabled (set PASARGUARD_TELEGRAM_BOT=1 to enable)");
}

/* --------------------------- dashboard ---------------------------- */

/* Copy the embedded archive out of this very file without ever materialising
   the 6 MB base64 blob or the 22 MB tarball in RAM — see extractTarFile(). */
function writeEmbeddedArchive(destFile) {
  const fd = fs.openSync(__filename, "r");
  const out = fs.openSync(destFile, "w");
  const begin = Buffer.from(DASH_BEGIN, "ascii");
  const end = Buffer.from(DASH_END, "ascii");
  const CH = 1 << 18;
  const buf = Buffer.allocUnsafe(CH);
  let carry = Buffer.alloc(0);
  let scanning = true;
  let pos = 0;
  let total = 0;
  try {
    for (;;) {
      let n = 0;
      try {
        n = fs.readSync(fd, buf, 0, CH, pos);
      } catch (e) {
        n = 0;
      }
      if (!n) break;
      pos += n;
      let data = carry.length ? Buffer.concat([carry, buf.subarray(0, n)]) : buf.subarray(0, n);
      if (scanning) {
        const i = data.indexOf(begin);
        if (i < 0) {
          carry = Buffer.from(data.subarray(Math.max(0, data.length - begin.length + 1)));
          continue;
        }
        data = data.subarray(i + begin.length);
        scanning = false;
      }
      const j = data.indexOf(end);
      if (j >= 0) {
        const d = b64Feed(data.subarray(0, j));
        if (d.length) {
          fs.writeSync(out, d);
          total += d.length;
        }
        break;
      }
      const hold = end.length - 1;
      const slice = data.subarray(0, Math.max(0, data.length - hold));
      if (slice.length) {
        const d = b64Feed(slice);
        if (d.length) {
          fs.writeSync(out, d);
          total += d.length;
        }
      }
      carry = Buffer.from(data.subarray(Math.max(0, data.length - hold)));
    }
  } finally {
    try {
      fs.closeSync(fd);
    } catch (e) {}
    try {
      fs.closeSync(out);
    } catch (e) {}
  }
  return total;
}

async function installDashboard(force) {
  const indexHtml = path.join(DASH_DIR, "index.html");
  if (!force && fs.existsSync(indexHtml) && fs.statSync(indexHtml).size > 500) {
    ok("dashboard assets present");
    return true;
  }
  step("unpacking the built dashboard");
  ensureDir(TMP);
  const brPath = path.join(TMP, `kb-dash-${process.pid}.br`);
  let wrote = 0;
  try {
    wrote = writeEmbeddedArchive(brPath);
  } catch (e) {
    warn("cannot read wrapper source: " + e.message);
    return false;
  }
  if (wrote < 1000) {
    warn("no embedded dashboard found in this file");
    try {
      fs.unlinkSync(brPath);
    } catch (e) {}
    return false;
  }
  rmrf(DASH_DIR);
  ensureDir(DASH_DIR);
  let n = 0;
  try {
    n = await extractCompressedTar(brPath, DASH_DIR, 0, "brotli");
  } catch (e) {
    warn("cannot decompress dashboard: " + e.message);
    n = 0;
  }
  try {
    fs.unlinkSync(brPath);
  } catch (e) {}
  if (!n) return false;
  ok(`dashboard unpacked (${n} files)`);
  return true;
}

/* ---------------------------- python deps -------------------------- */

const DEV_EXCLUDE = new Set([
  "pasarguard",
  "ruff",
  "pytest",
  "pytest-asyncio",
  "pytest-watch",
  "httpx",
  "psycopg",
  "pymysql",
  "sqlalchemy-utils",
  "watchfiles",
  "asyncmy",
  "coverage",
]);

function buildPins() {
  const lockPath = path.join(APP, "uv.lock");
  let pins = [];
  if (fs.existsSync(lockPath)) {
    const txt = fs.readFileSync(lockPath, "utf8");
    for (const block of txt.split("[[package]]").slice(1)) {
      const n = block.match(/^name = "([^"]+)"/m);
      const v = block.match(/^version = "([^"]+)"/m);
      if (!n || !v) continue;
      if (DEV_EXCLUDE.has(n[1].toLowerCase())) continue;
      pins.push(`${n[1]}==${v[1]}`);
    }
  }
  if (!pins.length) throw new Error("could not derive dependency pins from uv.lock");
  pins = ["setuptools", "wheel"].concat(pins.sort());
  fs.writeFileSync(PINS_FILE, pins.join("\n") + "\n");
  return pins.length;
}

async function createVenv(py) {
  if (fs.existsSync(path.join(VENV, "bin", "python")) || fs.existsSync(path.join(VENV, "bin", "python3"))) {
    return path.join(VENV, "bin", "python");
  }
  rmrf(VENV);
  step("creating virtualenv");
  let r = await run(py, ["-m", "venv", VENV], { quiet: true, timeout: 300000 });
  let exe = path.join(VENV, "bin", "python");
  if (r.code !== 0 || !fs.existsSync(exe)) {
    warn("venv module unavailable, installing virtualenv");
    await run(py, ["-m", "pip", "install", "--user", "virtualenv"], { quiet: true, timeout: 600000 });
    r = await run(py, ["-m", "virtualenv", VENV], { quiet: true, timeout: 600000 });
  }
  if (!fs.existsSync(exe)) throw new Error("could not create a virtualenv:\n" + r.out.slice(-800));
  return exe;
}

async function pipInstall(exe, timeoutMs) {
  const r = await run(
    exe,
    ["-m", "pip", "install", "--no-cache-dir", "--prefer-binary", "--disable-pip-version-check", "-r", PINS_FILE],
    { quiet: true, timeout: timeoutMs, filter: /ERROR|error:|Failed|failed|Successfully|Collecting|Building wheel/i }
  );
  return r;
}

async function installDependencies(py) {
  const exe = path.join(VENV, "bin", "python");
  const sentinel = path.join(VENV, ".pg-installed");
  if (fs.existsSync(exe) && fs.existsSync(sentinel)) {
    const v = await pyEval(exe, "import fastapi,sqlalchemy,uvicorn;print('ok')", { quiet: true });
    if (v === "ok") {
      ok("python dependencies present");
      return exe;
    }
  }
  step("installing python dependencies (from uv.lock)");
  const n = buildPins();
  log(`     ${n} pinned packages`);
  const venvExe = await createVenv(py);
  let r = await pipInstall(venvExe, 1500000);
  if (r.code !== 0) {
    // retry once: some wheels may be missing, allow source builds
    warn("first pip pass failed, retrying");
    const r2 = await run(
      venvExe,
      ["-m", "pip", "install", "--no-cache-dir", "-r", PINS_FILE],
      { quiet: true, timeout: 1500000, filter: /ERROR|error:|Failed|Successfully/i }
    );
    if (r2.code !== 0) throw new Error("pip install failed:\n" + r2.out.slice(-1500));
  }
  const check = await pyEval(venvExe, "import fastapi,sqlalchemy,uvicorn,aiosqlite,nats,aiogram;print('ok')", {
    quiet: true,
  });
  if (check !== "ok") throw new Error("dependency check failed after install");
  fs.writeFileSync(sentinel, new Date().toISOString());
  ok("python dependencies installed");
  releaseMemory();
  return venvExe;
}

/* ----------------------------- xray -------------------------------- */

function archNames() {
  const a = process.arch;
  return {
    node: a === "arm64" ? "arm64" : a === "x64" ? "amd64" : "amd64",
    xray: a === "arm64" ? "arm64-v8a" : "64",
  };
}

async function latestXrayVersion() {
  if (XRAY_VERSION && XRAY_VERSION !== "latest") return XRAY_VERSION;
  try {
    const r = await request("https://api.github.com/repos/XTLS/Xray-core/releases/latest", { timeout: 15000 });
    const j = JSON.parse(r.body.toString());
    if (j && j.tag_name) return j.tag_name;
  } catch (e) {}
  return "v26.3.27";
}

async function extractZipWith(py, zipPath, destDir, wanted) {
  ensureDir(destDir);
  const script = `
import zipfile, sys, os
z = zipfile.ZipFile(${JSON.stringify(zipPath)})
names = z.namelist()
want = ${JSON.stringify(wanted)}
for n in names:
    base = os.path.basename(n)
    if base in want:
        with open(os.path.join(${JSON.stringify(destDir)}, base), "wb") as f:
            f.write(z.read(n))
        print("extracted", base)
`;
  const r = await run(py, ["-c", script], { quiet: true, timeout: 120000, cwd: destDir });
  return r.code === 0;
}

async function installXray(py) {
  const exe = path.join(XRAY_DIR, "xray");
  if (fs.existsSync(exe) && fs.existsSync(path.join(XRAY_DIR, "geoip.dat"))) {
    const v = await run(exe, ["version"], { quiet: true, timeout: 30000 });
    if (v.code === 0) {
      STATE.xray = (v.out || "").split("\n")[0].trim();
      ok(`xray-core present (${STATE.xray})`);
      return exe;
    }
  }
  step("downloading xray-core");
  const ver = await latestXrayVersion();
  const arch = archNames().xray;
  const zipPath = path.join(TMP, "xray.zip");
  await downloadFile(
    `https://github.com/XTLS/Xray-core/releases/download/${ver}/Xray-linux-${arch}.zip`,
    zipPath,
    "xray-core " + ver
  );
  const okExtract = await extractZipWith(py, zipPath, XRAY_DIR, ["xray", "geoip.dat", "geosite.dat"]);
  rmrf(zipPath);
  if (!okExtract || !fs.existsSync(exe)) throw new Error("xray-core extraction failed");
  try { fs.chmodSync(exe, 0o755); } catch (e) {}
  const v = await run(exe, ["version"], { quiet: true, timeout: 30000 });
  STATE.xray = (v.out || "").split("\n")[0].trim();
  ok(`xray-core ${ver} installed (${STATE.xray || "ok"})`);
  return exe;
}

/* ------------------------- pasarguard node ------------------------- */

async function makeCerts(py) {
  const cert = path.join(CERT_DIR, "ssl_cert.pem");
  const key = path.join(CERT_DIR, "ssl_key.pem");
  if (fs.existsSync(cert) && fs.existsSync(key)) return { cert, key };
  step("generating TLS certificate for the local node");
  const subject = "/CN=pg-node";
  const san = "subjectAltName=DNS:localhost,IP:127.0.0.1";
  let r = await run(
    "openssl",
    ["req", "-x509", "-newkey", "ec", "-pkeyopt", "ec_paramgen_curve:prime256v1", "-keyout", key, "-out", cert,
      "-days", "3650", "-nodes", "-subj", subject, "-addext", san],
    { quiet: true, timeout: 60000, cwd: CERT_DIR }
  );
  if (r.code !== 0) {
    r = await run(
      "openssl",
      ["req", "-x509", "-newkey", "rsa:2048", "-keyout", key, "-out", cert, "-days", "3650", "-nodes",
        "-subj", subject, "-addext", san],
      { quiet: true, timeout: 120000, cwd: CERT_DIR }
    );
  }
  if (r.code !== 0 || !fs.existsSync(cert)) {
    // last resort: generate with the cryptography library inside the venv
    const script = `
from cryptography import x509
from cryptography.x509.oid import NameOID
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
import datetime
key = ec.generate_private_key(ec.SECP256R1())
name = x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, "pg-node")])
now = datetime.datetime.now(datetime.timezone.utc)
cert = (x509.CertificateBuilder().subject_name(name).issuer_name(name)
        .public_key(key.public_key()).serial_number(x509.random_serial_number())
        .not_valid_before(now).not_valid_after(now + datetime.timedelta(days=3650))
        .add_extension(x509.SubjectAlternativeName([x509.DNSName("localhost"), x509.IPAddress(__import__("ipaddress").ip_address("127.0.0.1"))]), critical=False)
        .sign(key, hashes.SHA256()))
open(${JSON.stringify(cert)}, "wb").write(cert.public_bytes(serialization.Encoding.PEM))
open(${JSON.stringify(key)}, "wb").write(key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
print("ok")
`;
    const r2 = await run(py, ["-c", script], { quiet: true, timeout: 120000 });
    if (r2.code !== 0) throw new Error("could not generate a TLS certificate:\n" + (r.out || "") + (r2.out || ""));
  }
  ok("TLS certificate ready");
  return { cert, key };
}

async function installNode(py) {
  const arch = archNames().node;
  const exe = path.join(NODE_DIR, "pasarguard-node");
  if (!fs.existsSync(exe)) {
    step(`downloading PasarGuard node ${NODE_VERSION}`);
    const zipPath = path.join(TMP, "pgnode.zip");
    await downloadFile(
      `https://github.com/${NODE_REPO}/releases/download/${NODE_VERSION}/pasarguard-node-linux-${arch}.zip`,
      zipPath,
      "pasarguard-node"
    );
    const okExtract = await extractZipWith(py, zipPath, NODE_DIR, [`pasarguard-node-linux-${arch}`]);
    rmrf(zipPath);
    if (!okExtract) throw new Error("pasarguard-node extraction failed");
    const raw = path.join(NODE_DIR, `pasarguard-node-linux-${arch}`);
    if (fs.existsSync(raw)) fs.renameSync(raw, exe);
    if (!fs.existsSync(exe)) throw new Error("pasarguard-node binary not found after extraction");
    try { fs.chmodSync(exe, 0o755); } catch (e) {}
    ok(`pasarguard-node ${NODE_VERSION} installed`);
  } else {
    ok(`pasarguard-node present (${NODE_VERSION})`);
  }
  STATE.node = NODE_VERSION;
  return exe;
}

function nodeApiKey() {
  try {
    const k = fs.readFileSync(NODE_KEY_FILE, "utf8").trim();
    if (/^[0-9a-f-]{36}$/i.test(k)) return k;
  } catch (e) {}
  const k = uuid4();
  fs.writeFileSync(NODE_KEY_FILE, k);
  return k;
}

function writeNodeEnv(key, cert, keyFile) {
  const body = [
    `SERVICE_PORT = ${NODE_PORT}`,
    'NODE_HOST = "127.0.0.1"',
    "",
    `XRAY_EXECUTABLE_PATH = ${path.join(XRAY_DIR, "xray")}`,
    `XRAY_ASSETS_PATH = ${XRAY_DIR}`,
    "",
    `SSL_CERT_FILE = ${cert}`,
    `SSL_KEY_FILE = ${keyFile}`,
    "",
    `API_KEY = ${key}`,
    'SERVICE_PROTOCOL = "grpc"',
    "",
    `GENERATED_CONFIG_PATH = ${path.join(NODE_DIR, "generated")}`,
    "",
  ].join("\n");
  fs.writeFileSync(NODE_ENV_FILE, body);
}

function writePanelEnv() {
  const lines = [
    "## generated by pasarguard-katabump — edit only if you know what you are doing",
    `UVICORN_HOST = "127.0.0.1"`,
    `UVICORN_PORT = ${PANEL_PORT}`,
    `SQLALCHEMY_DATABASE_URL = "sqlite+aiosqlite:///${DB_FILE}"`,
    'ROLE = "all-in-one"',
    'SUBSCRIPTION_PATH = "sub"',
    'ALLOWED_ORIGINS = "*"',
    'DASHBOARD_PATH = "/dashboard/"',
    "DOCS = true",
    `STOP_NODES_ON_SHUTDOWN = true`,
  ];
  if (!TELEGRAM_BOT) lines.push('PASARGUARD_TELEGRAM_BOT = "0"');
  fs.writeFileSync(ENV_FILE, lines.join("\n") + "\n");
}

async function migrate(py) {
  step("running database migrations");
  const r = await run(py, ["-m", "alembic", "upgrade", "head"], {
    quiet: true,
    timeout: 600000,
    cwd: APP,
    env: { SQLALCHEMY_DATABASE_URL: `sqlite+aiosqlite:///${DB_FILE}`, PYTHONUNBUFFERED: "1" },
  });
  if (r.code !== 0) throw new Error("alembic upgrade failed:\n" + r.out.slice(-1500));
  ok("database ready");
}
/* ================================================================== *
 *  runtime: processes, provisioning, public port, watchdog           *
 * ================================================================== */

const CHILD = { panel: null, node: null, xray: null };

function openLog(name) {
  return fs.openSync(path.join(LOGS, name), "a");
}

function spawnLogged(cmd, args, opts, name, logName) {
  const fd = openLog(logName);
  const child = spawn(cmd, args, Object.assign({ stdio: ["ignore", fd, fd], detached: false }, opts));
  child.on("exit", (code) => {
    log(`${name} exited (code ${code})`);
  });
  child._logFd = fd;
  return child;
}

async function startPanel(py) {
  CHILD.panel = spawnLogged(
    py,
    ["-u", "main.py"],
    { cwd: APP, env: Object.assign({}, process.env, { PYTHONUNBUFFERED: "1", TZ: process.env.TZ || "UTC" }) },
    "panel",
    "panel.log"
  );
  return CHILD.panel;
}

function startNodeProcess(exe) {
  CHILD.node = spawnLogged(
    exe,
    [],
    { cwd: NODE_DIR, env: Object.assign({}, process.env, { TZ: process.env.TZ || "UTC" }) },
    "pasarguard-node",
    "node.log"
  );
  return CHILD.node;
}

async function waitForPanel(timeoutMs = 240000) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (CHILD.panel && CHILD.panel.exitCode !== null) {
      const tail = tailFile(path.join(LOGS, "panel.log"), 25);
      throw new Error("panel process exited during startup:\n" + tail);
    }
    try {
      const r = await request(`http://127.0.0.1:${PANEL_PORT}/health`, { timeout: 3000 });
      if (r.status === 200) return true;
    } catch (e) {}
    await sleep(1000);
  }
  throw new Error("panel did not become ready in time:\n" + tailFile(path.join(LOGS, "panel.log"), 30));
}

function rssOf(pid) {
  try {
    const s = fs.readFileSync(`/proc/${pid}/statm`, "utf8").split(" ");
    return (Number(s[1]) * 4096) / 1048576; // resident pages -> MB
  } catch (e) {
    return 0;
  }
}

function tailFile(file, lines) {
  try {
    const s = fs.readFileSync(file, "utf8");
    return s.split("\n").slice(-lines).join("\n");
  } catch (e) {
    return "(no log)";
  }
}

/* ------------------------------- api ------------------------------ */

async function api(method, urlPath, { token, json: body, form, timeout } = {}) {
  const headers = {};
  let payload = null;
  if (body !== undefined) {
    headers["Content-Type"] = "application/json";
    payload = JSON.stringify(body);
  } else if (form !== undefined) {
    headers["Content-Type"] = "application/x-www-form-urlencoded";
    payload = form;
  }
  if (token) headers["Authorization"] = "Bearer " + token;
  const r = await request(`http://127.0.0.1:${PANEL_PORT}${urlPath}`, {
    method,
    headers,
    body: payload,
    timeout: timeout || 20000,
  });
  let parsed = null;
  try {
    parsed = JSON.parse(r.body.toString());
  } catch (e) {
    parsed = r.body.toString();
  }
  return { status: r.status, data: parsed };
}

async function login(user, password) {
  const r = await api("POST", "/api/admin/token", {
    form: `username=${encodeURIComponent(user)}&password=${encodeURIComponent(password)}&grant_type=password`,
  });
  if (r.status === 200 && r.data && r.data.access_token) return r.data.access_token;
  return null;
}

function strongPassword(seed) {
  // policy: >=12 chars, >=2 digits, >=2 upper, >=2 lower, >=1 special, must not contain the username
  const base = seed && seed.length >= 8 ? seed : "Katabump" + randomToken(6);
  let p = base.replace(/[^A-Za-z0-9!@#$%^&*_\-]/g, "");
  if (!/[A-Z]/.test(p)) p += "AB";
  if (p.replace(/[^A-Z]/g, "").length < 2) p += "CD";
  if (p.replace(/[^0-9]/g, "").length < 2) p += "19" + (p.length % 10) + "8";
  if (!/[!@#$%^&*_\-]/.test(p)) p += "!";
  if (p.length < 12) p += "Kb" + randomToken(4) + "9";
  if (p.toLowerCase().includes(ADMIN_USER.toLowerCase())) p = p.replace(new RegExp(ADMIN_USER, "ig"), "Kb");
  return p.slice(0, 40);
}

async function generateTempKey(py) {
  const r = await run(py, ["pasarguard-cli.py", "generate-temp-key"], {
    quiet: true,
    timeout: 120000,
    cwd: APP,
    env: { SQLALCHEMY_DATABASE_URL: `sqlite+aiosqlite:///${DB_FILE}` },
  });
  const clean = (r.out || "").replace(/\x1b\[[0-9;]*m/g, "");
  const m = clean.match(/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/);
  if (!m) throw new Error("could not get a temp key:\n" + clean.slice(-400));
  return m[0];
}

async function ensureOwner(py) {
  let password = ADMIN_PASS || readState().adminPass || "";
  const creds = { user: ADMIN_USER, password: password };

  // Non-destructive probe: an unused key is never consumed, and the 409 check in the
  // endpoint runs BEFORE the key is validated, so a bogus key tells us whether an
  // owner exists without creating or changing anything.
  const probe = await api("POST", "/api/setup/owner", {
    json: { key: "00000000-0000-0000-0000-000000000000", username: "__probe__", password: "Xx123456789!aB" },
  });
  const ownerExists =
    probe.status === 409 || (probe.data && probe.data.detail === "owner already exists");

  if (ownerExists) {
    if (password && (await login(creds.user, password))) {
      ok("owner account already exists");
      creds.password = password;
      return creds;
    }
    // we do not know the password: reset it with a fresh one-time key
    if (!password) password = strongPassword("Katabump" + randomToken(5));
    const key = await generateTempKey(py);
    const r = await api("PATCH", "/api/setup/owner", { json: { key, password } });
    if (r.status !== 200) {
      throw new Error("could not reset the owner password: " + JSON.stringify(r.data).slice(0, 300));
    }
    saveState({ adminPass: password, adminUser: ADMIN_USER });
    ok("owner password reset");
    creds.password = password;
    return creds;
  }

  if (!password) password = strongPassword("Katabump" + randomToken(5));
  creds.password = password;
  const key2 = await generateTempKey(py);
  const r = await api("POST", "/api/setup/owner", {
    json: { key: key2, username: ADMIN_USER, password: password },
  });
  if (r.status !== 201 && r.status !== 200) {
    throw new Error("could not create the owner account: " + JSON.stringify(r.data).slice(0, 400));
  }
  saveState({ adminPass: password, adminUser: ADMIN_USER });
  ok(`owner account created (${ADMIN_USER})`);
  return creds;
}

function coreConfig() {
  return {
    log: { loglevel: "warning" },
    dns: { servers: ["https+local://8.8.8.8/dns-query", "localhost"] },
    routing: {
      domainStrategy: "AsIs",
      rules: [
        { type: "field", inboundTag: [INBOUND_TAG], outboundTag: "direct" },
        { type: "field", ip: ["geoip:private"], outboundTag: "blocked" },
      ],
    },
    outbounds: [
      { protocol: "freedom", tag: "direct" },
      { protocol: "blackhole", tag: "blocked" },
    ],
    inbounds: [
      {
        tag: INBOUND_TAG,
        listen: "127.0.0.1",
        port: XRAY_PORT,
        protocol: "vless",
        settings: { clients: [], decryption: "none" },
        streamSettings: {
          network: "ws",
          wsSettings: { path: TUNNELS[0].path },
          security: "none",
        },
        sniffing: { enabled: true, destOverride: ["http", "tls"] },
      },
    ],
  };
}

async function ensureCore(token) {
  const list = await api("GET", "/api/cores", { token });
  if (list.status === 200 && Array.isArray(list.data)) {
    for (const c of list.data) {
      try {
        if ((c.config && c.config.inbounds || []).some((i) => i.tag === INBOUND_TAG)) {
          ok(`core config present (${c.name || c.id})`);
          return c.id;
        }
      } catch (e) {}
    }
    for (const c of list.data) {
      ok(`reusing core config (${c.name || c.id})`);
      return c.id;
    }
  }
  const r = await api("POST", "/api/core", {
    token,
    json: { name: "katabump-core", type: "xray", config: coreConfig() },
  });
  if (r.status !== 200 && r.status !== 201) {
    throw new Error("could not create the core config: " + JSON.stringify(r.data).slice(0, 400));
  }
  ok("core config created");
  return r.data.id;
}

async function ensureNodeRegistration(token, coreId, key, certPem) {
  const list = await api("GET", "/api/nodes", { token });
  const nodes = list.status === 200 && list.data && list.data.nodes ? list.data.nodes : [];
  if (nodes.length) {
    ok(`node registered (${nodes[0].name || nodes[0].id}, status ${nodes[0].status || "?"})`);
    return nodes[0].id;
  }
  const r = await api("POST", "/api/node", {
    token,
    json: {
      name: "katabump-local",
      address: "127.0.0.1",
      port: NODE_PORT,
      api_port: NODE_API_PORT,
      connection_type: "grpc",
      server_ca: certPem,
      keep_alive: 30,
      core_config_id: coreId,
      api_key: key,
      usage_coefficient: 1,
    },
  });
  if (r.status !== 200 && r.status !== 201) {
    throw new Error("could not register the node: " + JSON.stringify(r.data).slice(0, 600));
  }
  ok("local node registered");
  return r.data.id;
}

async function ensureHost(token, publicHost) {
  const list = await api("GET", "/api/hosts", { token });
  const hosts = list.status === 200 && Array.isArray(list.data) ? list.data : [];
  const wantPort = PUBLIC_PORT;
  const wantAddress = publicHost || "127.0.0.1";
  const body = {
    remark: "Katabump VLESS WS",
    address: [wantAddress],
    inbound_tag: INBOUND_TAG,
    port: wantPort,
    path: TUNNELS[0].path,
    security: "inbound_default",
    is_disabled: false,
    priority: 1,
  };
  let existing = hosts.find((h) => h.inbound_tag === INBOUND_TAG);
  if (existing) {
    const same =
      existing.port === wantPort &&
      Array.isArray(existing.address) &&
      existing.address[0] === wantAddress &&
      (existing.path || "") === TUNNELS[0].path;
    if (!same) {
      const r = await api("PUT", `/api/host/${existing.id}`, { token, json: body });
      if (r.status === 200) ok(`host updated to ${wantAddress}:${wantPort}${TUNNELS[0].path}`);
      else warn("could not update the host: " + JSON.stringify(r.data).slice(0, 200));
    } else {
      ok(`host present (${wantAddress}:${wantPort}${TUNNELS[0].path})`);
    }
    return existing.id;
  }
  const r = await api("POST", "/api/host/", { token, json: body });
  if (r.status !== 200 && r.status !== 201) {
    throw new Error("could not create the host: " + JSON.stringify(r.data).slice(0, 400));
  }
  ok(`host created (${wantAddress}:${wantPort}${TUNNELS[0].path})`);
  return r.data.id;
}

async function ensureGroup(token) {
  const list = await api("GET", "/api/groups", { token });
  const groups = list.status === 200 && Array.isArray(list.data) ? list.data : [];
  const found = groups.find((g) => Array.isArray(g.inbound_tags) && g.inbound_tags.includes(INBOUND_TAG));
  if (found) {
    ok(`group present (${found.name})`);
    return found.id;
  }
  const r = await api("POST", "/api/group", {
    token,
    json: { name: "katabump-default", inbound_tags: [INBOUND_TAG], is_disabled: false },
  });
  if (r.status !== 200 && r.status !== 201) {
    throw new Error("could not create the group: " + JSON.stringify(r.data).slice(0, 400));
  }
  ok("default group created (users must be in it to receive configs)");
  return r.data.id;
}

async function autoGroupUsers(token, groupId) {
  if (!AUTO_GROUP || !groupId) return;
  const r = await api("GET", "/api/users?size=200", { token, timeout: 25000 });
  const users = r.status === 200 && r.data && Array.isArray(r.data.users) ? r.data.users : [];
  let fixed = 0;
  for (const u of users) {
    const ids = u.group_ids || [];
    if (ids.length) continue;
    const put = await api("PUT", `/api/user/${encodeURIComponent(u.username)}`, {
      token,
      json: { group_ids: [groupId] },
      timeout: 25000,
    });
    if (put.status === 200) fixed++;
  }
  if (fixed) log(`     added ${fixed} user(s) to the default group`);
}

/* --------------------------- public port -------------------------- */

function statusHtml() {
  const s = STATE;
  const esc = (x) => String(x == null ? "" : x).replace(/[<>&]/g, (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;" })[c]);
  const tunnels = (s.tunnels || [])
    .map((t) => `<tr><td>${esc(t.proto)}</td><td><code>${esc(t.path)}</code></td><td>${t.port}</td></tr>`)
    .join("");
  const color = s.error ? "#ff6b6b" : s.panelUp ? "#4ade80" : "#fbbf24";
  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>PasarGuard</title>
<style>body{margin:0;background:#0b1020;color:#e6e9f2;font:15px/1.6 system-ui,-apple-system,Segoe UI,sans-serif}
.wrap{max-width:760px;margin:0 auto;padding:32px 20px}
h1{font-size:22px;margin:0 0 4px}.sub{color:#8b93ad;margin-bottom:24px}
.card{background:#111832;border:1px solid #1f2a44;border-radius:14px;padding:20px;margin-bottom:16px}
.dot{display:inline-block;width:10px;height:10px;border-radius:50%;background:${color};margin-right:8px}
table{width:100%;border-collapse:collapse;margin-top:8px}td,th{padding:6px 8px;border-bottom:1px solid #1f2a44;text-align:left;font-size:14px}
code{background:#0b1020;padding:2px 6px;border-radius:6px;font-size:13px}
a{color:#7dd3fc}</style></head><body><div class="wrap">
<h1><span class="dot"></span>PasarGuard on KataBump</h1>
<div class="sub">${esc(WRAPPER)} — panel ${esc(s.pasarguard || "?")} · node ${esc(s.node || "?")}</div>
<div class="card"><b>Status:</b> ${esc(s.step)} ${s.error ? "— " + esc(s.error) : ""}<br>
<b>Public port:</b> ${s.publicPort} · <b>Panel:</b> 127.0.0.1:${s.panelPort} (${s.panelUp ? "up" : "down"}) · <b>Core:</b> ${s.coreUp ? "up" : "down"}<br>
<b>Public host:</b> ${esc(s.publicHost || "detecting…")}</div>
<div class="card"><b>Links</b><br>
<a href="/dashboard/">/dashboard/</a> — web panel<br>
<a href="/docs">/docs</a> — API docs · <a href="/health">/health</a> — health</div>
<div class="card"><b>Tunnels</b><table><tr><th>proto</th><th>path</th><th>local port</th></tr>${tunnels}</table></div>
</div></body></html>`;
}

function writeResponse(socket, status, body, ctype, extraHeaders) {
  const b = Buffer.from(body);
  let head = `HTTP/1.1 ${status}\r\nContent-Type: ${ctype}\r\nContent-Length: ${b.length}\r\nCache-Control: no-store\r\n`;
  if (extraHeaders) for (const k of Object.keys(extraHeaders)) head += `${k}: ${extraHeaders[k]}\r\n`;
  head += "Connection: close\r\n\r\n";
  try {
    socket.end(Buffer.concat([Buffer.from(head, "latin1"), b]));
  } catch (e) {
    try { socket.destroy(); } catch (e2) {}
  }
}

function withForwarded(buf, ip) {
  const s = buf.toString("latin1");
  const idx = s.indexOf("\r\n");
  if (idx < 0) return buf;
  const hostMatch = s.match(/\r\nHost:\s*([^\r\n]*)/i);
  const extra =
    `X-Forwarded-For: ${ip}\r\nX-Forwarded-Proto: http\r\n` +
    (hostMatch ? `X-Forwarded-Host: ${hostMatch[1].trim()}\r\n` : "");
  return Buffer.from(s.slice(0, idx + 2) + extra + s.slice(idx + 2), "latin1");
}

function startProxy() {
  const server = net.createServer((client) => {
    client.setNoDelay(true);
    let first = null;
    const onData = (chunk) => {
      if (first) return;
      first = chunk;
      client.removeListener("data", onData);
      route(client, first, client.remoteAddress || "127.0.0.1");
    };
    client.on("data", onData);
    client.on("error", () => {});
    client.on("end", () => {
      if (!first) client.destroy();
    });
  });
  server.on("error", (e) => {
    err("public port error: " + e.message);
    STATE.error = e.message;
  });
  return new Promise((resolve) => {
    server.listen(PUBLIC_PORT, "0.0.0.0", () => resolve(server));
  });
}

function route(client, buf, ip) {
  const head = buf.toString("latin1");
  const line = head.split("\r\n")[0] || "";
  const [, urlPath] = line.split(" ");
  const clean = (urlPath || "/").split("?")[0];

  // wrapper endpoints
  if (clean === STATUS_PATH) {
    const body = JSON.stringify(STATE, null, 2);
    const html = /text\/html/.test(head);
    return writeResponse(client, 200, html ? statusHtml() : body, html ? "text/html; charset=utf-8" : "application/json");
  }
  if (clean === "/" || clean === "") {
    return writeResponse(
      client,
      302,
      "",
      "text/plain",
      { Location: "/dashboard/" }
    );
  }

  // tunnel paths go straight to xray
  const tun = TUNNELS.find((t) => clean === t.path || clean.startsWith(t.path + "/"));
  const targetPort = tun ? tun.port : PANEL_PORT;

  if (!STATE.panelUp && !tun) {
    return writeResponse(
      client,
      503,
      statusHtml().replace("<title>PasarGuard</title>", "<title>PasarGuard — starting</title>"),
      "text/html; charset=utf-8"
    );
  }

  const upstream = net.connect({ host: "127.0.0.1", port: targetPort }, () => {
    // tunnels (websocket) go to xray untouched; HTTP traffic to the panel gets forwarded headers
    upstream.write(tun ? buf : withForwarded(buf, ip));
    upstream.pipe(client);
    client.pipe(upstream);
  });
  upstream.on("error", () => {
    try {
      client.end(
        "HTTP/1.1 502 Bad Gateway\r\nContent-Type: text/plain\r\nContent-Length: 21\r\nConnection: close\r\n\r\nupstream unavailable\n"
      );
    } catch (e) {}
  });
  client.on("error", () => {
    try { upstream.destroy(); } catch (e) {}
  });
  upstream.setNoDelay(true);
}

/* ---------------------------- watchdog ---------------------------- */

let lastAutoGroup = 0;
async function watchdog(py, nodeExe, ctx) {
  releaseMemory();
  while (true) {
    await sleep(20000);
    try {
      // panel
      let up = await portOpen(PANEL_PORT, 1500);
      if (up) {
        try {
          const r = await request(`http://127.0.0.1:${PANEL_PORT}/health`, { timeout: 5000 });
          up = r.status === 200;
        } catch (e) {
          up = false;
        }
      }
      // memory safety valve: restart the panel before the container OOM-kills us
      const panelRss = CHILD.panel ? rssOf(CHILD.panel.pid) : 0;
      STATE.panelRss = Math.round(panelRss);
      if (up && panelRss > PANEL_MEM_MAX) {
        warn(`panel is using ${Math.round(panelRss)} MB (ceiling ${PANEL_MEM_MAX} MB) — restarting it`);
        up = false;
      }
      if (!up) {
        warn("panel is down — restarting");
        if (CHILD.panel) { try { CHILD.panel.kill("SIGKILL"); } catch (e) {} }
        STATE.panelUp = false;
        await sleep(2000);
        await startPanel(py);
        await waitForPanel(180000);
        STATE.panelUp = true;
        ok("panel is back");
      } else {
        STATE.panelUp = true;
      }

      // node + xray
      if (!SKIP_XRAY) {
        const nodeUp = await portOpen(NODE_PORT, 1500);
        if (!nodeUp && CHILD.node && CHILD.node.exitCode === null) {
          // node restarted by the panel? give it a moment
        }
        if (!nodeUp && (!CHILD.node || CHILD.node.exitCode !== null)) {
          warn("pasarguard-node stopped — restarting");
          startNodeProcess(nodeExe);
          await sleep(4000);
        }
        const xrayUp = await portOpen(XRAY_PORT, 1500);
        STATE.coreUp = xrayUp;
        if (!xrayUp) log("     xray inbound not listening (panel will restart the core)");
      }

      // keep users grouped
      if (ctx.token && ctx.groupId && Date.now() - lastAutoGroup > 60000) {
        lastAutoGroup = Date.now();
        try {
          await autoGroupUsers(ctx.token, ctx.groupId);
        } catch (e) {}
      }
      releaseMemory();
    } catch (e) {
      log("watchdog: " + e.message);
    }
  }
}

/* ----------------------------- banner ----------------------------- */

function writeCredFile(user, password, publicHost) {
  const host = publicHost || "YOUR-SERVER-IP";
  const lines = [
    "PasarGuard on KataBump",
    "=======================",
    "",
    `Panel      : http://${host}:${PUBLIC_PORT}/dashboard/`,
    `API docs   : http://${host}:${PUBLIC_PORT}/docs`,
    `Status     : http://${host}:${PUBLIC_PORT}${STATUS_PATH}`,
    "",
    `Username   : ${user}`,
    `Password   : ${password}`,
    "",
    `Xray core  : ${STATE.xray || "unknown"}`,
    `Node       : PasarGuard node ${STATE.node || "?"} on 127.0.0.1:${NODE_PORT}`,
    `Inbound    : ${INBOUND_TAG} -> 127.0.0.1:${XRAY_PORT} (ws path ${TUNNELS[0].path})`,
    `Host entry : ${host}:${PUBLIC_PORT}${TUNNELS[0].path}`,
    "",
    "Data (persistent): " + DATA,
    "Logs              : " + LOGS,
    "",
  ];
  try {
    fs.writeFileSync(CRED_FILE, lines.join("\n"));
  } catch (e) {}
  return lines.join("\n");
}

function banner(user, password, publicHost) {
  const host = publicHost || "YOUR-SERVER-IP";
  const line = "─".repeat(64);
  console.log("");
  console.log(paint("35", "  " + line));
  console.log(paint("35", "   PasarGuard is ready"));
  console.log(paint("35", "  " + line));
  console.log(`   panel     http://${host}:${PUBLIC_PORT}/dashboard/`);
  console.log(`   api docs  http://${host}:${PUBLIC_PORT}/docs`);
  console.log(`   status    http://${host}:${PUBLIC_PORT}${STATUS_PATH}`);
  console.log("");
  console.log(`   username  ${user}`);
  console.log(`   password  ${password}`);
  console.log("");
  console.log(`   panel ${STATE.pasarguard || "?"} · node ${STATE.node || "?"} · ${STATE.xray || "xray"}`);
  console.log(`   data  ${DATA}`);
  console.log(paint("35", "  " + line));
  console.log("");
}

/* ---------------------------- selftest ---------------------------- */

async function selfTest() {
  log("selftest: checking structure only (no network)");
  const checks = [
    ["wrapper constants", typeof WRAPPER === "string" && typeof PUBLIC_PORT === "number"],
    ["tunnels parsed", Array.isArray(TUNNELS) && TUNNELS.length > 0],
    ["tar parser", typeof extractTarBuf === "function"],
    ["password policy", (() => { const p = strongPassword("Katabump123"); return p.length >= 12 && /[A-Z].*[A-Z]/.test(p) && /[0-9].*[0-9]/.test(p) && /[!@#$%^&*_\-]/.test(p); })()],
    ["core config json", (() => { const c = coreConfig(); return c.inbounds[0].tag === INBOUND_TAG && c.inbounds[0].port === XRAY_PORT; })()],
    ["dashboard blob markers", (() => {
      try {
        const s = fs.readFileSync(__filename, "utf8");
        const a = s.indexOf(DASH_BEGIN);
        const b = s.indexOf(DASH_END);
        if (a < 0 || b < 0) return false;
        const b64 = s.slice(a + DASH_BEGIN.length, b).replace(/[^A-Za-z0-9+/=]/g, "");
        if (b64.length < 1000) return false;
        const buf = Buffer.from(b64, "base64");
        let tar;
        try { tar = zlib.brotliDecompressSync(buf); } catch (e) { tar = zlib.gunzipSync(buf); }
        return tar.length > 100000 && tar.toString("latin1", 0, 5).length === 5;
      } catch (e) {
        return false;
      }
    })()],
    ["python-2 except fixer", (() => {
      return /^(\s*)except\s+/.test("    except ValueError, KeyError:") && EXCEPT_RE.source.length > 0;
    })()],
  ];
  let bad = 0;
  for (const [name, pass] of checks) {
    console.log(`   ${pass ? paint("32", "✓") : paint("31", "✗")} ${name}`);
    if (!pass) bad++;
  }
  console.log(`   ${bad ? paint("31", bad + " failed") : paint("32", "all good")}`);
  process.exit(bad ? 1 : 0);
}

/* ------------------------------ main ------------------------------ */

async function bootstrap() {
  ensureDirs();
  killOrphans();

  step("opening public port " + PUBLIC_PORT);
  await startProxy();
  ok("public port " + PUBLIC_PORT + " open");
  releaseMemory();

  const py = await findPython();
  STATE.python = py;
  releaseMemory();

  await installPanelSource(FORCE_SETUP);
  STATE.pasarguard = panelVersion();
  releaseMemory();

  await patchSources(py);
  releaseMemory();

  const dashOk = await installDashboard(FORCE_SETUP);
  STATE.dashboard = dashOk;
  releaseMemory();

  const venvPy = await installDependencies(py);
  releaseMemory();

  writePanelEnv();
  await migrate(venvPy);
  releaseMemory();

  let nodeExe = null;
  if (!SKIP_XRAY) {
    await installXray(venvPy);
    releaseMemory();
    nodeExe = await installNode(venvPy);
    const { cert, key: keyFile } = await makeCerts(venvPy);
    const key = nodeApiKey();
    writeNodeEnv(key, cert, keyFile);
    STATE.nodeCert = cert;
    startNodeProcess(nodeExe);
    await sleep(2500);
    if (await portOpen(NODE_PORT, 2000)) ok(`pasarguard-node listening on 127.0.0.1:${NODE_PORT}`);
    else warn("pasarguard-node did not open its port yet (the panel will retry)");
    releaseMemory();
  }

  step("starting the panel");
  await startPanel(venvPy);
  await waitForPanel();
  STATE.panelUp = true;
  ok(`panel up on 127.0.0.1:${PANEL_PORT}`);
  releaseMemory();

  step("provisioning");
  const creds = await ensureOwner(venvPy);
  releaseMemory();

  const token = await login(creds.user, creds.password);
  if (!token) throw new Error("could not log in to the panel with the owner account");
  ok("logged in to the API");

  const publicHost = await detectPublicIp();
  STATE.publicHost = publicHost;

  const coreId = await ensureCore(token);
  const ctx = { token };
  if (!SKIP_XRAY) {
    const certPem = fs.readFileSync(path.join(CERT_DIR, "ssl_cert.pem"), "utf8");
    await ensureNodeRegistration(token, coreId, nodeApiKey(), certPem);
  }
  await ensureHost(token, publicHost);
  ctx.groupId = await ensureGroup(token);
  await autoGroupUsers(token, ctx.groupId);
  releaseMemory();

  step("waiting for xray to start");
  let coreUp = false;
  for (let i = 0; i < 30; i++) {
    coreUp = await portOpen(XRAY_PORT, 1500);
    if (coreUp) break;
    await sleep(2000);
  }
  STATE.coreUp = coreUp;
  if (coreUp) ok(`xray inbound listening on 127.0.0.1:${XRAY_PORT}`);
  else warn("xray inbound is not listening yet — check " + path.join(LOGS, "node.log"));

  STATE.step = "ready";
  STATE.admin = creds.user;
  saveState({ adminUser: creds.user, adminPass: creds.password, publicHost });

  writeCredFile(creds.user, creds.password, publicHost);
  banner(creds.user, creds.password, publicHost);
  releaseMemory();

  watchdog(venvPy, nodeExe, ctx);
}

function shutdown(sig) {
  log("shutting down (" + sig + ")");
  for (const k of ["panel", "node"]) {
    const c = CHILD[k];
    if (c && c.exitCode === null) {
      try { c.kill("SIGTERM"); } catch (e) {}
    }
  }
  setTimeout(() => process.exit(0), 1500).unref();
}

async function main() {
  console.log("");
  console.log(paint("35", "  pasarguard-katabump ") + paint("90", WRAPPER));
  console.log(paint("90", "  PasarGuard " + PG_VERSION + " · node " + NODE_VERSION + " · single public port " + PUBLIC_PORT));
  console.log("");
  if (process.env.SELFTEST === "1") return selfTest();

  // keep ports from colliding
  const used = new Set([PUBLIC_PORT]);
  const pick = async (preferred, fallbackStart) => {
    if (!used.has(preferred) && !(await portOpen(preferred, 400))) {
      used.add(preferred);
      return preferred;
    }
    const p = await firstFreePort([fallbackStart, fallbackStart + 1, fallbackStart + 2, fallbackStart + 3]);
    used.add(p);
    return p;
  };
  PANEL_PORT = await pick(PANEL_PORT, 8000);
  NODE_PORT = await pick(NODE_PORT, 62050);
  NODE_API_PORT = NODE_PORT + 1;
  XRAY_PORT = await pick(XRAY_PORT, 21001);
  TUNNELS[0].port = XRAY_PORT;
  STATE.panelPort = PANEL_PORT;

  try {
    await bootstrap();
  } catch (e) {
    STATE.error = e.message;
    STATE.step = "error";
    err(e.message);
    console.log("");
    console.log("  logs: " + LOGS);
    throw e;
  }
}

process.on("SIGTERM", () => shutdown("SIGTERM"));
process.on("SIGINT", () => shutdown("SIGINT"));

main().catch((e) => {
  if (process.env.SELFTEST !== "1") process.exitCode = 1;
});

